from typing import Dict, List, Sequence, Tuple


def split_shipment(lines: Sequence[Tuple[str, int, int]], max_parcel_grams: int) -> List[Dict[str, int]]:
    """Split an order into parcels under a carrier weight limit.

    Same-SKU lines are merged first (they must share a unit weight). A merged
    line whose total weight fits within max_parcel_grams is packed as ONE item
    and never split across parcels; only lines heavier than the limit are broken
    into single units. Packing uses first-fit-decreasing with the SKU as item id.

    Raises ValueError if max_parcel_grams <= 0, a qty or unit weight is <= 0, a
    single unit is heavier than max_parcel_grams, or a SKU has two unit weights.
    """
    if max_parcel_grams <= 0:
        raise ValueError("max_parcel_grams must be > 0")

    merged: Dict[str, Tuple[int, int]] = {}
    for sku, qty, uw in lines:
        if qty <= 0:
            raise ValueError(f"qty for {sku} must be > 0")
        if uw <= 0:
            raise ValueError(f"unit weight for {sku} must be > 0")
        if sku in merged:
            if merged[sku][1] != uw:
                raise ValueError(f"SKU {sku} has different unit weights")
            merged[sku] = (merged[sku][0] + qty, uw)
        else:
            merged[sku] = (qty, uw)

    items: List[Tuple[str, int, int, int]] = []
    for order, (sku, (qty, uw)) in enumerate(merged.items()):
        if uw > max_parcel_grams:
            raise ValueError(f"single unit of {sku} heavier than max_parcel_grams")
        if qty * uw <= max_parcel_grams:
            items.append((sku, qty * uw, 0, order))
        else:
            for _ in range(qty):
                items.append((sku, uw, 1, order))

    items.sort(key=lambda it: (-it[1], it[2], it[3]))

    bins: List[Dict[str, int]] = []
    rem: List[int] = []
    for sku, w, _, _ in items:
        placed = False
        for i, r in enumerate(rem):
            if r >= w:
                bins[i][sku] = bins[i].get(sku, 0) + (1 if w == 0 else 1)
                rem[i] = r - w
                placed = True
                break
        if not placed:
            bins.append({sku: 1})
            rem.append(max_parcel_grams - w)
    return bins
